function validate(input) {
  const [urls, edges, startUrl] = input;
  if (!Array.isArray(urls) || urls.length < 1 || urls.length > 1000) return 'Give 1 to 1000 urls.';
  const shape = /^http:\/\/([a-z0-9.-]{1,63})(\/[\x21-\x7e]*)?$/;
  for (const url of urls) {
    const match = typeof url === 'string' ? shape.exec(url) : null;
    if (!match || url.length > 300) return `"${url}" is not a url of the form http://hostname/path with at most 300 characters.`;
    if (match[1].startsWith('-') || match[1].endsWith('-')) return `The hostname of "${url}" starts or ends with a hyphen.`;
  }
  if (new Set(urls).size !== urls.length) return 'The urls must be distinct.';
  if (!Array.isArray(edges) || edges.length > 2000) return 'Give at most 2000 edges.';
  for (const edge of edges) {
    if (!Array.isArray(edge) || edge.length !== 2 || !edge.every((i) => Number.isInteger(i) && i >= 0 && i < urls.length)) return 'Each edge is [a, b] with indexes into urls.';
  }
  if (!urls.includes(startUrl)) return 'startUrl must be one of the urls.';
  return null;
}

