function adapt(input, solve, kit) {
  const [urls, edges, startUrl] = input;
  const links = new Map(urls.map((url) => [url, []]));
  for (const [from, to] of edges) links.get(urls[from]).push(urls[to]);
  const hostOf = (url) => url.split('/')[2];
  const fetched = new Set();
  // The link lists stay inside this closure; the solution can only call getUrls.
  const htmlParser = Object.freeze({
    getUrls(url) {
      if (!links.has(url)) throw new Error(`getUrls was called with ${JSON.stringify(url)}, which is not one of the urls.`);
      if (hostOf(url) !== hostOf(startUrl)) throw new Error(`getUrls was called for ${url}, which is on another hostname.`);
      if (fetched.has(url)) throw new Error(`getUrls was called twice for ${url}.`);
      fetched.add(url);
      return [...links.get(url)];
    },
  });
  const result = solve(startUrl, htmlParser);
  if (!Array.isArray(result)) throw new Error('crawl must return an array of urls.');
  return result;
}

