function crawl(startUrl, htmlParser) {
  const hostname = (url) => url.split('/')[2];
  const host = hostname(startUrl);
  const seen = new Set([startUrl]);
  const queue = [startUrl];
  let front = 0;
  while (front < queue.length) {
    const url = queue[front];
    front++;
    for (const link of htmlParser.getUrls(url)) {
      if (seen.has(link) || hostname(link) !== host) {
        continue;
      }
      seen.add(link);
      queue.push(link);
    }
  }
  return [...seen];
}

