function crawl(startUrl, htmlParser) {
  const hostOf = (url) => /^http:\/\/([^/]*)/.exec(url)[1];
  const found = [];
  // Depth-first: enter a page only if it is new and on the start page's hostname.
  const explore = (url) => {
    if (found.includes(url) || hostOf(url) !== hostOf(startUrl)) return;
    found.push(url);
    for (const next of htmlParser.getUrls(url)) explore(next);
  };
  explore(startUrl);
  return found;
}

