function generate(rand, size) {
  const pick = (k) => Math.floor(rand() * k);
  const small = size === 'small';
  const pool = ['news.yahoo.com', 'yahoo.com', 'news.google.com', 'leetcode.com', 'a.leetcode.com', 'leetcode.com.cn', 'my-site.org', 'x1.y2'];
  const hosts = [];
  const hostCount = small ? 1 + pick(3) : 3 + pick(4);
  while (hosts.length < hostCount) {
    const host = pool[pick(pool.length)];
    if (!hosts.includes(host)) hosts.push(host);
  }
  const parts = ['news', 'us', 'topics', 'a', 'b', 'leetcode.com', 'q?x=1', 'p#top'];
  const count = small ? 1 + pick(7) : 700 + pick(301);
  const urls = [];
  const known = new Set();
  const home = [];
  for (let tries = 0; urls.length < count && tries < 50 * count; tries++) {
    // Most pages share the first hostname, so the crawl has something to do.
    const host = rand() < 0.6 ? hosts[0] : hosts[pick(hosts.length)];
    let path = '';
    if (small) {
      const depth = pick(3);
      for (let d = 0; d < depth; d++) path += `/${parts[pick(parts.length)]}`;
      if (rand() < 0.25) path += '/';
    } else {
      path = `/${parts[pick(parts.length)]}/${urls.length}`;
    }
    const url = `http://${host}${path}`;
    if (known.has(url)) continue;
    known.add(url);
    if (host === hosts[0]) home.push(urls.length);
    urls.push(url);
  }
  const edges = [];
  const edgeCount = small ? pick(2 * urls.length + 1) : 2000;
  // A long chain through the first hostname's pages, then random links (cycles, self-links, foreign pages).
  for (let k = 0; k + 1 < home.length && edges.length < edgeCount; k++) if (rand() < 0.75) edges.push([home[k], home[k + 1]]);
  while (edges.length < edgeCount) edges.push([pick(urls.length), pick(urls.length)]);
  const start = home.length > 0 && rand() < 0.8 ? home[pick(small ? home.length : Math.min(home.length, 5))] : pick(urls.length);
  return [urls, edges, urls[start]];
}
